PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','leader','employee')), enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS teams(id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memberships(id INTEGER PRIMARY KEY,user_id TEXT REFERENCES users(id),team_id TEXT REFERENCES teams(id),valid_from REAL NOT NULL,valid_to REAL);
CREATE INDEX IF NOT EXISTS membership_time ON memberships(user_id,valid_from,valid_to);
CREATE TABLE IF NOT EXISTS leaderships(id INTEGER PRIMARY KEY,user_id TEXT REFERENCES users(id),team_id TEXT REFERENCES teams(id),valid_from REAL NOT NULL,valid_to REAL,temporary INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS devices(id TEXT PRIMARY KEY,label TEXT,client_key TEXT,enabled INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS bindings(id INTEGER PRIMARY KEY,user_id TEXT REFERENCES users(id),device_id TEXT REFERENCES devices(id),valid_from REAL,valid_to REAL);
CREATE TABLE IF NOT EXISTS areas(id TEXT PRIMARY KEY,name TEXT,kind TEXT CHECK(kind IN ('work','restricted')));
CREATE TABLE IF NOT EXISTS area_versions(id TEXT PRIMARY KEY,area_id TEXT REFERENCES areas(id),polygon TEXT NOT NULL,valid_from REAL NOT NULL,valid_to REAL,actor_id TEXT,reason TEXT);
CREATE INDEX IF NOT EXISTS area_version_time ON area_versions(area_id,valid_from,valid_to);
CREATE TABLE IF NOT EXISTS allocations(id INTEGER PRIMARY KEY,user_id TEXT REFERENCES users(id),area_id TEXT REFERENCES areas(id),valid_from REAL,valid_to REAL,actor_id TEXT);
CREATE TABLE IF NOT EXISTS work_sessions(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),started_at REAL NOT NULL,ended_at REAL,end_reason TEXT,purpose TEXT,last_contact_at REAL,last_assessed_at REAL);
CREATE UNIQUE INDEX IF NOT EXISTS one_open_session ON work_sessions(user_id) WHERE ended_at IS NULL;
CREATE TABLE IF NOT EXISTS session_areas(id INTEGER PRIMARY KEY,session_id TEXT REFERENCES work_sessions(id),area_id TEXT REFERENCES areas(id),valid_from REAL NOT NULL,valid_to REAL,recorded_at REAL NOT NULL,actor_id TEXT,task_id TEXT);
CREATE TABLE IF NOT EXISTS leases(id TEXT PRIMARY KEY,session_id TEXT REFERENCES work_sessions(id),user_id TEXT REFERENCES users(id),device_id TEXT REFERENCES devices(id),token_hash TEXT UNIQUE,tab_id TEXT,valid_from REAL,valid_to REAL,source TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_live_lease ON leases(user_id) WHERE valid_to IS NULL;
CREATE TABLE IF NOT EXISTS observations(id INTEGER PRIMARY KEY,point_id TEXT NOT NULL,user_id TEXT REFERENCES users(id),session_id TEXT REFERENCES work_sessions(id),device_id TEXT,lease_id TEXT,observed_at REAL NOT NULL,received_at REAL NOT NULL,x REAL,y REAL,lat REAL,lng REAL,accuracy REAL NOT NULL,source TEXT NOT NULL,team_id TEXT,area_id TEXT,area_version_id TEXT,assessment TEXT,source_observed_at TEXT,UNIQUE(user_id,point_id));
CREATE INDEX IF NOT EXISTS observation_user_time ON observations(user_id,observed_at,id);
CREATE INDEX IF NOT EXISTS observation_team_time ON observations(team_id,observed_at);
CREATE INDEX IF NOT EXISTS observation_session ON observations(session_id,observed_at);
CREATE TABLE IF NOT EXISTS transfers(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),from_area TEXT,to_area TEXT,origin_team_id TEXT,owner_team_id TEXT,created_by TEXT,created_at REAL,started_at REAL,allowed_seconds INTEGER,original_deadline REAL,deadline REAL,status TEXT,claimed_arrival_at REAL,effective_arrival_at REAL,confirmed_at REAL,reason TEXT,next_instruction TEXT,overdue_notified INTEGER DEFAULT 0);
CREATE UNIQUE INDEX IF NOT EXISTS one_open_transfer ON transfers(user_id) WHERE status IN ('pending','in_transit','arrival_pending');
CREATE TABLE IF NOT EXISTS transfer_actions(id INTEGER PRIMARY KEY,transfer_id TEXT REFERENCES transfers(id),actor_id TEXT,action TEXT,at REAL,data TEXT);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),team_id TEXT,session_id TEXT,kind TEXT,area_id TEXT,area_version_id TEXT,started_at REAL,last_at REAL,recovered_at REAL,observation_state TEXT,workflow TEXT,evidence TEXT,created_at REAL,escalated INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS event_actions(id INTEGER PRIMARY KEY,event_id TEXT REFERENCES events(id),actor_id TEXT,action TEXT,at REAL,text TEXT);
CREATE TABLE IF NOT EXISTS detector_state(user_id TEXT,area_id TEXT,kind TEXT,version_id TEXT,candidate TEXT,streak INTEGER,last_at REAL,active_event_id TEXT,PRIMARY KEY(user_id,area_id,kind));
CREATE TABLE IF NOT EXISTS help_requests(id TEXT PRIMARY KEY,client_id TEXT,user_id TEXT REFERENCES users(id),team_id TEXT,category TEXT,description TEXT,photo TEXT,position_json TEXT,status TEXT,owner_id TEXT,proxy_id TEXT,created_at REAL,updated_at REAL,escalated INTEGER DEFAULT 0,UNIQUE(user_id,client_id));
CREATE TABLE IF NOT EXISTS help_actions(id INTEGER PRIMARY KEY,help_id TEXT REFERENCES help_requests(id),actor_id TEXT,action TEXT,at REAL,text TEXT);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,user_id TEXT REFERENCES users(id),title TEXT,entity_type TEXT,entity_id TEXT,created_at REAL,read_at REAL);
CREATE TABLE IF NOT EXISTS shifts(id TEXT PRIMARY KEY,name TEXT,start_time TEXT,end_time TEXT,leader_id TEXT REFERENCES users(id),enabled INTEGER DEFAULT 1,duty_date TEXT);
CREATE TABLE IF NOT EXISTS report_snapshots(id TEXT PRIMARY KEY,created_by TEXT,created_at REAL,body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,actor_id TEXT,action TEXT,entity_type TEXT,entity_id TEXT,at REAL,data TEXT);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS evaluations(id TEXT PRIMARY KEY,created_by TEXT,created_at REAL,body TEXT);

CREATE TABLE IF NOT EXISTS site_map_assets(id TEXT PRIMARY KEY,name TEXT NOT NULL,width_px INTEGER NOT NULL,height_px INTEGER NOT NULL,sha256 TEXT NOT NULL,image_data BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS site_map_versions(id TEXT PRIMARY KEY,asset_id TEXT NOT NULL REFERENCES site_map_assets(id),name TEXT NOT NULL,origin_x REAL NOT NULL,origin_y REAL NOT NULL,meters_per_pixel REAL NOT NULL CHECK(meters_per_pixel>0),valid_from REAL NOT NULL,valid_to REAL,actor_id TEXT NOT NULL,reason TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_current_site_map ON site_map_versions((1)) WHERE valid_to IS NULL;

CREATE TABLE IF NOT EXISTS inspections(id TEXT PRIMARY KEY,assignee_id TEXT REFERENCES users(id),assigned_by TEXT,team_id TEXT,area_id TEXT,status TEXT,note TEXT,created_at REAL,started_at REAL,finished_at REAL);
CREATE INDEX IF NOT EXISTS inspection_assignee ON inspections(assignee_id,status);
CREATE UNIQUE INDEX IF NOT EXISTS one_open_inspection ON inspections(assignee_id) WHERE status IN ('assigned','in_progress');
CREATE TABLE IF NOT EXISTS inspection_findings(id TEXT PRIMARY KEY,inspection_id TEXT REFERENCES inspections(id),target TEXT,subject_user_id TEXT,problem INTEGER NOT NULL,category TEXT,description TEXT,event_id TEXT,created_at REAL,actor_id TEXT);
